using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;

public class Cv
{
    public int W, H;
    public uint[] P;

    public Cv(int w, int h) { W = w; H = h; P = new uint[w * h]; }

    public static uint C(string hex) { return 0xFF000000u | Convert.ToUInt32(hex, 16); }

    public uint Get(int x, int y)
    {
        if (x < 0 || y < 0 || x >= W || y >= H) return 0;
        return P[y * W + x];
    }

    public void Set(int x, int y, uint c)
    {
        if (x < 0 || y < 0 || x >= W || y >= H) return;
        P[y * W + x] = c;
    }

    static bool In(uint v, uint[] on)
    {
        if (on == null) return true;
        for (int i = 0; i < on.Length; i++) if (on[i] == v) return true;
        return false;
    }

    public void Rect(int x, int y, int w, int h, uint c)
    {
        for (int yy = y; yy < y + h; yy++)
            for (int xx = x; xx < x + w; xx++) Set(xx, yy, c);
    }

    public void RectOn(int x, int y, int w, int h, uint c, uint[] on)
    {
        for (int yy = y; yy < y + h; yy++)
            for (int xx = x; xx < x + w; xx++)
                if (In(Get(xx, yy), on) && Get(xx, yy) != 0) Set(xx, yy, c);
    }

    public void Line(int x0, int y0, int x1, int y1, uint c) { LineOn(x0, y0, x1, y1, c, null); }

    public void LineOn(int x0, int y0, int x1, int y1, uint c, uint[] on)
    {
        int dx = Math.Abs(x1 - x0), dy = -Math.Abs(y1 - y0);
        int sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1;
        int err = dx + dy;
        while (true)
        {
            if (on == null || (Get(x0, y0) != 0 && In(Get(x0, y0), on))) Set(x0, y0, c);
            if (x0 == x1 && y0 == y1) break;
            int e2 = 2 * err;
            if (e2 >= dy) { err += dy; x0 += sx; }
            if (e2 <= dx) { err += dx; y0 += sy; }
        }
    }

    public void LineT(int x0, int y0, int x1, int y1, int t, uint c)
    {
        int dx = Math.Abs(x1 - x0), dy = -Math.Abs(y1 - y0);
        int sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1;
        int err = dx + dy;
        int o = t / 2;
        while (true)
        {
            Rect(x0 - o, y0 - o, t, t, c);
            if (x0 == x1 && y0 == y1) break;
            int e2 = 2 * err;
            if (e2 >= dy) { err += dy; x0 += sx; }
            if (e2 <= dx) { err += dx; y0 += sy; }
        }
    }

    public void Ell(double cx, double cy, double rx, double ry, uint c)
    {
        int x0 = (int)Math.Floor(cx - rx) - 1, x1 = (int)Math.Ceiling(cx + rx) + 1;
        int y0 = (int)Math.Floor(cy - ry) - 1, y1 = (int)Math.Ceiling(cy + ry) + 1;
        for (int y = y0; y <= y1; y++)
            for (int x = x0; x <= x1; x++)
            {
                double dx = (x + 0.5 - cx) / rx, dy = (y + 0.5 - cy) / ry;
                if (dx * dx + dy * dy <= 1.0) Set(x, y, c);
            }
    }

    public void Ring(double cx, double cy, double rx, double ry, double t, uint c)
    {
        int x0 = (int)Math.Floor(cx - rx) - 1, x1 = (int)Math.Ceiling(cx + rx) + 1;
        int y0 = (int)Math.Floor(cy - ry) - 1, y1 = (int)Math.Ceiling(cy + ry) + 1;
        double irx = Math.Max(0.5, rx - t), iry = Math.Max(0.5, ry - t);
        for (int y = y0; y <= y1; y++)
            for (int x = x0; x <= x1; x++)
            {
                double dx = (x + 0.5 - cx) / rx, dy = (y + 0.5 - cy) / ry;
                double ex = (x + 0.5 - cx) / irx, ey = (y + 0.5 - cy) / iry;
                if (dx * dx + dy * dy <= 1.0 && ex * ex + ey * ey > 1.0) Set(x, y, c);
            }
    }

    public bool Inside(double[] pts, double px, double py)
    {
        bool inside = false;
        int n = pts.Length / 2;
        for (int i = 0, j = n - 1; i < n; j = i++)
        {
            double xi = pts[i * 2], yi = pts[i * 2 + 1], xj = pts[j * 2], yj = pts[j * 2 + 1];
            if (((yi > py) != (yj > py)) && (px < (xj - xi) * (py - yi) / (yj - yi) + xi)) inside = !inside;
        }
        return inside;
    }

    public void Poly(double[] pts, uint c) { PolyOn(pts, c, null); }

    public void PolyOn(double[] pts, uint c, uint[] on)
    {
        double minx = 1e9, maxx = -1e9, miny = 1e9, maxy = -1e9;
        for (int i = 0; i < pts.Length / 2; i++)
        {
            minx = Math.Min(minx, pts[i * 2]); maxx = Math.Max(maxx, pts[i * 2]);
            miny = Math.Min(miny, pts[i * 2 + 1]); maxy = Math.Max(maxy, pts[i * 2 + 1]);
        }
        for (int y = (int)Math.Floor(miny); y <= (int)Math.Ceiling(maxy); y++)
            for (int x = (int)Math.Floor(minx); x <= (int)Math.Ceiling(maxx); x++)
                if (Inside(pts, x + 0.5, y + 0.5))
                {
                    if (on == null || (Get(x, y) != 0 && In(Get(x, y), on))) Set(x, y, c);
                }
    }

    public void Replace(uint from, uint to)
    {
        for (int i = 0; i < P.Length; i++) if (P[i] == from) P[i] = to;
    }

    // Luz arriba-izquierda: bordes superior/izquierdo claros, inferior/derecho oscuros
    public void Bevel(uint baseC, uint light, uint dark)
    {
        uint[] s = (uint[])P.Clone();
        for (int y = 0; y < H; y++)
            for (int x = 0; x < W; x++)
            {
                if (s[y * W + x] != baseC) continue;
                uint up = Gs(s, x, y - 1), lf = Gs(s, x - 1, y), dn = Gs(s, x, y + 1), rt = Gs(s, x + 1, y);
                if (up != baseC || lf != baseC) P[y * W + x] = light;
                else if (dn != baseC || rt != baseC) P[y * W + x] = dark;
            }
    }

    // Solo sombra inferior/derecha sobre un color (para volumen sin borde claro)
    public void ShadeBR(uint baseC, uint dark)
    {
        uint[] s = (uint[])P.Clone();
        for (int y = 0; y < H; y++)
            for (int x = 0; x < W; x++)
            {
                if (s[y * W + x] != baseC) continue;
                if (Gs(s, x, y + 1) != baseC || Gs(s, x + 1, y) != baseC) P[y * W + x] = dark;
            }
    }

    uint Gs(uint[] s, int x, int y)
    {
        if (x < 0 || y < 0 || x >= W || y >= H) return 0;
        return s[y * W + x];
    }

    public void Noise(uint baseC, uint alt, int percent, int seed)
    {
        Random rng = new Random(seed);
        for (int i = 0; i < P.Length; i++)
            if (P[i] == baseC && rng.Next(100) < percent) P[i] = alt;
    }

    public void Outline(uint c)
    {
        uint[] s = (uint[])P.Clone();
        for (int y = 0; y < H; y++)
            for (int x = 0; x < W; x++)
            {
                if (s[y * W + x] != 0) continue;
                if (Gs(s, x - 1, y) != 0 || Gs(s, x + 1, y) != 0 || Gs(s, x, y - 1) != 0 || Gs(s, x, y + 1) != 0)
                    P[y * W + x] = c;
            }
    }

    public void Rim(uint baseC, uint rim)
    {
        uint[] s = (uint[])P.Clone();
        for (int y = 0; y < H; y++)
            for (int x = 0; x < W; x++)
            {
                if (s[y * W + x] != baseC) continue;
                if (Gs(s, x - 1, y) == 0 || Gs(s, x + 1, y) == 0 || Gs(s, x, y - 1) == 0 || Gs(s, x, y + 1) == 0)
                    P[y * W + x] = rim;
            }
    }

    public void Mirror()
    {
        for (int y = 0; y < H; y++)
            for (int x = 0; x < W / 2; x++)
            {
                uint v = P[y * W + x];
                if (v != 0) P[y * W + (W - 1 - x)] = v;
            }
    }

    public void Stamp(Cv o, int ox, int oy)
    {
        for (int y = 0; y < o.H; y++)
            for (int x = 0; x < o.W; x++)
            {
                uint v = o.P[y * o.W + x];
                if (v != 0) Set(ox + x, oy + y, v);
            }
    }

    public string[] ColorHex()
    {
        HashSet<uint> hs = new HashSet<uint>();
        for (int i = 0; i < P.Length; i++) if (P[i] != 0) hs.Add(P[i]);
        List<string> l = new List<string>();
        foreach (uint v in hs) l.Add((v & 0xFFFFFF).ToString("X6"));
        return l.ToArray();
    }

    public int[] BBox()
    {
        int minx = W, miny = H, maxx = -1, maxy = -1;
        for (int y = 0; y < H; y++)
            for (int x = 0; x < W; x++)
                if (P[y * W + x] != 0)
                {
                    if (x < minx) minx = x; if (x > maxx) maxx = x;
                    if (y < miny) miny = y; if (y > maxy) maxy = y;
                }
        return new int[] { minx, miny, maxx, maxy };
    }

    public Bitmap ToBitmap()
    {
        Bitmap bmp = new Bitmap(W, H, PixelFormat.Format32bppArgb);
        BitmapData bd = bmp.LockBits(new Rectangle(0, 0, W, H), ImageLockMode.WriteOnly, PixelFormat.Format32bppArgb);
        int[] d = new int[P.Length];
        Buffer.BlockCopy(P, 0, d, 0, P.Length * 4);
        Marshal.Copy(d, 0, bd.Scan0, d.Length);
        bmp.UnlockBits(bd);
        return bmp;
    }

    public void Save(string path)
    {
        using (Bitmap bmp = ToBitmap()) bmp.Save(path, ImageFormat.Png);
    }
}

public static class Sheet
{
    public static void Build(List<Cv> imgs, List<string> names, int cols, int cell, string path)
    {
        int rows = (imgs.Count + cols - 1) / cols;
        int labelH = 14;
        using (Bitmap bmp = new Bitmap(cols * cell, rows * (cell + labelH), PixelFormat.Format32bppArgb))
        using (Graphics g = Graphics.FromImage(bmp))
        using (Font f = new Font("Consolas", 7f))
        using (Brush tb = new SolidBrush(Color.FromArgb(200, 200, 210)))
        using (Brush bg1 = new SolidBrush(Color.FromArgb(58, 60, 72)))
        using (Brush bg2 = new SolidBrush(Color.FromArgb(48, 50, 62)))
        {
            g.InterpolationMode = InterpolationMode.NearestNeighbor;
            g.PixelOffsetMode = PixelOffsetMode.Half;
            g.Clear(Color.FromArgb(40, 42, 52));
            for (int i = 0; i < imgs.Count; i++)
            {
                int cx = (i % cols) * cell, cy = (i / cols) * (cell + labelH);
                g.FillRectangle(((i % cols + i / cols) % 2 == 0) ? bg1 : bg2, cx, cy, cell, cell + labelH);
                using (Bitmap b = imgs[i].ToBitmap())
                {
                    int ox = cx + (cell - imgs[i].W) / 2;
                    int oy = cy + (cell - imgs[i].H) / 2;
                    g.DrawImage(b, ox, oy, imgs[i].W, imgs[i].H);
                }
                g.DrawString(names[i], f, tb, cx + 2, cy + cell);
            }
            bmp.Save(path, ImageFormat.Png);
        }
    }
}

