$global:Imgs = New-Object 'System.Collections.Generic.List[Cv]'
$global:ImgNames = New-Object 'System.Collections.Generic.List[string]'
$global:Results = New-Object System.Collections.ArrayList

function New-Canvas([int]$w, [int]$h) { $global:g = New-Object Cv($w, $h) }

function Done([string]$name, [string]$cat, [string]$desc, [switch]$NoOutline) {
  if (-not $NoOutline) { $global:g.Outline($global:K) }
  $path = Join-Path $global:OutDir ($name + '.png')
  $global:g.Save($path)
  $hex = $global:g.ColorHex()
  $off = @($hex | Where-Object { -not $global:AllowedHex.ContainsKey($_) })
  $bb = $global:g.BBox()
  [void]$global:Results.Add([pscustomobject]@{
    Name = $name; Cat = $cat; Desc = $desc; W = $global:g.W; H = $global:g.H
    BW = $bb[2] - $bb[0] + 1; BH = $bb[3] - $bb[1] + 1
    Colors = $hex.Count; Off = ($off -join ',')
  })
  $global:Imgs.Add($global:g)
  $global:ImgNames.Add($name)
}

# Llama (capas de fuego). cx = centro, by = base, w = semiancho, h = alto
function Flame([double]$cx, [double]$by, [double]$w, [double]$h) {
  $layers = @(@(1.0, $global:f0), @(0.88, $global:f1), @(0.62, $global:f2), @(0.38, $global:f3))
  foreach ($l in $layers) {
    $s = $l[0]; $ww = $w * $s; $hh = $h * $s
    $global:g.Poly(@(($cx + 0.15 * $ww), ($by - $hh), ($cx + 0.55 * $ww), ($by - 0.62 * $hh), ($cx + $ww), ($by - 0.3 * $hh), $cx, $by, ($cx - $ww), ($by - 0.3 * $hh), ($cx - 0.5 * $ww), ($by - 0.66 * $hh)), $l[1])
    $global:g.Ell($cx, ($by - 0.28 * $hh), $ww, (0.28 * $hh), $l[1])
  }
  $global:g.Ell($cx, ($by - 0.14 * $h), (0.2 * $w + 0.5), (0.14 * $h), $global:b3)
}

# Espejo de una lista plana de puntos respecto a un eje vertical (x -> axis*2 - x)
function Mir([double[]]$pts, [double]$axis) {
  $o = New-Object 'double[]' $pts.Length
  for ($n = 0; $n -lt $pts.Length; $n += 2) { $o[$n] = $axis * 2 - $pts[$n]; $o[$n + 1] = $pts[$n + 1] }
  return , $o
}

# ================= TILES 64x64 (sin contorno, repetibles) =================

function BrickTile([int]$bh, [bool]$stagger, $mortar, $tones, $hi, $lo, $nA, $nB, [int]$seed) {
  New-Canvas 64 64
  $bw = 32
  for ($y = 0; $y -lt 64; $y++) {
    for ($x = 0; $x -lt 64; $x++) {
      $row = [math]::Floor($y / $bh); $ry = $y % $bh
      $off = 0; if ($stagger) { $off = ($row % 2) * ($bw / 2) }
      $xx = ($x + $off) % 64; $bx = $xx % $bw; $idx = [math]::Floor($xx / $bw)
      if ($ry -eq ($bh - 1) -or $bx -eq ($bw - 1)) { $col = $mortar }
      else {
        $col = $tones[($row * 2 + $idx) % $tones.Count]
        if (($ry -eq 0 -and $bx -gt 0) -or ($bx -eq 0 -and $ry -gt 0)) { $col = $hi }
        elseif ($ry -eq ($bh - 2) -or $bx -eq ($bw - 2)) { $col = $lo }
      }
      $global:g.Set($x, $y, $col)
    }
  }
  $n = 0
  foreach ($t in ($tones | Select-Object -Unique)) {
    $global:g.Noise($t, $nA, 7, $seed + $n); $global:g.Noise($t, $nB, 5, $seed + 50 + $n); $n++
  }
}

