# --- suelo de madera ---
New-Canvas 64 64
for ($y = 0; $y -lt 64; $y++) {
  for ($x = 0; $x -lt 64; $x++) {
    $row = [math]::Floor($y / 8); $ry = $y % 8
    $off = ($row * 13) % 32; $bx = ($x + $off) % 32; $pi = [math]::Floor((($x + $off) % 64) / 32)
    $tone = $w2; if ((($row * 3 + $pi) % 3) -eq 1) { $tone = $w1 }
    if ($ry -eq 7 -or $bx -eq 31) { $col = $w0 }
    elseif ($ry -eq 0) { $col = $w4 }
    else { $col = $tone }
    $g.Set($x, $y, $col)
  }
}
$g.Noise($w2, $w0, 6, 5); $g.Noise($w2, $w4, 3, 6); $g.Noise($w1, $w0, 6, 7)
Done 'tile_suelo_madera' 'Tile' 'Entarimado de madera con juntas escalonadas' -NoOutline

# --- alfombra (repetir en X) ---
New-Canvas 64 64
for ($y = 0; $y -lt 64; $y++) {
  for ($x = 0; $x -lt 64; $x++) {
    $dx = [math]::Abs(($x % 32) - 16); $dy = [math]::Abs($y - 32); $d = $dx + $dy
    $col = $r1
    if ($y -ge 2 -and $y -le 3) { $col = $b1 }
    elseif ($y -eq 6 -or $y -eq 57) { $col = $r0 }
    elseif ($y -ge 60 -and $y -le 61) { $col = $b1 }
    elseif ($y -lt 2 -or $y -gt 61 -or $y -eq 4 -or $y -eq 5 -or $y -eq 58 -or $y -eq 59) { $col = $r0 }
    elseif ($y -gt 7 -and $y -lt 56) {
      if ($d -eq 16) { $col = $b1 }
      elseif ($d -ge 6 -and $d -le 8) { $col = $r2 }
      elseif ($d -lt 4) { $col = $r0 }
      elseif ($d -eq 12) { $col = $r0 }
    }
    $g.Set($x, $y, $col)
  }
}
