// Elipse con tramado: 0 solido, 1 damero, 2 disperso (1 de cada 4), 3 disperso desplazado
public void EllD(double cx, double cy, double rx, double ry, uint c, int mode)
{
    int x0 = (int)Math.Floor(cx - rx) - 1, x1 = (int)Math.Ceiling(cx + rx) + 1;
    int y0 = (int)Math.Floor(cy - ry) - 1, y1 = (int)Math.Ceiling(cy + ry) + 1;
    for (int y = y0; y <= y1; y++)
        for (int x = x0; x <= x1; x++)
        {
            double dx = (x + 0.5 - cx) / rx, dy = (y + 0.5 - cy) / ry;
            if (dx * dx + dy * dy > 1.0) continue;
            bool ok = true;
            if (mode == 1) ok = ((x + y) & 1) == 0;
            else if (mode == 2) ok = ((x & 1) == 0 && (y & 1) == 0);
            else if (mode == 3) ok = ((x & 1) == 1 && (y & 1) == 1);
            if (ok) Set(x, y, c);
        }
}

public static Cv Strip(List<Cv> fr)
{
    int tw = 0;
    for (int i = 0; i < fr.Count; i++) tw += fr[i].W;
    Cv s = new Cv(tw, fr[0].H);
    int ox = 0;
    for (int i = 0; i < fr.Count; i++) { s.Stamp(fr[i], ox, 0); ox += fr[i].W; }
    return s;
}

public void Ring(double cx, double cy, double rx, double ry, double t, uint c)

public static class Sheet
{
    public static void Strips(List<Cv> strips, List<string> names, int maxScale, int maxW, string path)
    {
        int labelH = 14;
        int[] sc = new int[strips.Count];
        int totalH = 0, totalW = 0;
        for (int i = 0; i < strips.Count; i++)
        {
            int s = maxScale;
            while (s > 1 && strips[i].W * s > maxW) s--;
            sc[i] = s;
            totalH += strips[i].H * s + labelH + 6;
            totalW = Math.Max(totalW, strips[i].W * s + 8);
        }
        using (Bitmap bmp = new Bitmap(totalW, totalH, PixelFormat.Format32bppArgb))
        using (Graphics g = Graphics.FromImage(bmp))
        using (Font f = new Font("Consolas", 7f))
        using (Brush tb = new SolidBrush(Color.FromArgb(200, 200, 210)))
        using (Brush bg1 = new SolidBrush(Color.FromArgb(58, 60, 72)))
        {
            g.InterpolationMode = InterpolationMode.NearestNeighbor;
            g.PixelOffsetMode = PixelOffsetMode.Half;
            g.Clear(Color.FromArgb(40, 42, 52));
            int y = 0;
            for (int i = 0; i < strips.Count; i++)
            {
                int w = strips[i].W * sc[i], h = strips[i].H * sc[i];
                g.DrawString(names[i], f, tb, 2, y);
                g.FillRectangle(bg1, 4, y + labelH, w, h);
                using (Bitmap b = strips[i].ToBitmap()) g.DrawImage(b, 4, y + labelH, w, h);
                y += h + labelH + 6;
            }
            bmp.Save(path, ImageFormat.Png);
        }
    }

