$global:VfxDir = Join-Path (Split-Path (Split-Path $PSScriptRoot)) 'vfx_castillo'
New-Item -ItemType Directory -Force -Path $global:VfxDir | Out-Null
$global:VfxResults = New-Object System.Collections.ArrayList
$global:VfxStrips = New-Object 'System.Collections.Generic.List[Cv]'
$global:VfxNames = New-Object 'System.Collections.Generic.List[string]'

# Genera n frames con el bloque $draw (param($f,$t)), guarda frames sueltos y hoja horizontal
function New-Vfx([string]$name, [int]$w, [int]$h, [int]$n, [int]$fps, [string]$loop, [int]$ax, [int]$ay, [string]$desc, [scriptblock]$draw, [switch]$Outline) {
  $dir = Join-Path $global:VfxDir $name
  New-Item -ItemType Directory -Force -Path $dir | Out-Null
  $frames = New-Object 'System.Collections.Generic.List[Cv]'
  $all = @{}
  for ($f = 0; $f -lt $n; $f++) {
    New-Canvas $w $h
    & $draw $f ($f / $n)
    if ($Outline) { $global:g.Outline($global:K) }
    $global:g.Save((Join-Path $dir ('{0}_{1:00}.png' -f $name, $f)))
    foreach ($hx in $global:g.ColorHex()) { $all[$hx] = $true }
    $frames.Add($global:g)
  }
  $strip = [Cv]::Strip($frames)
  $strip.Save((Join-Path $global:VfxDir ($name + '_sheet.png')))
  $off = @($all.Keys | Where-Object { -not $global:AllowedHex.ContainsKey($_) })
  [void]$global:VfxResults.Add([pscustomobject]@{
    Name = $name; W = $w; H = $h; N = $n; Fps = $fps; Loop = $loop; AX = $ax; AY = $ay
    Colors = $all.Count; Off = ($off -join ','); Desc = $desc
  })
  $global:VfxStrips.Add($strip); $global:VfxNames.Add("$name  ($n frames, ${w}x${h}, $fps fps)")
}

# Llama animada. tip = desplazamiento lateral de la punta. ramp = 5 colores (4 capas + nucleo)
function FlameA([double]$cx, [double]$by, [double]$w, [double]$h, [double]$tip, $ramp) {
  $layers = @(@(1.0, $ramp[0]), @(0.88, $ramp[1]), @(0.62, $ramp[2]), @(0.38, $ramp[3]))
  foreach ($l in $layers) {
    $s = $l[0]; $ww = $w * $s; $hh = $h * $s; $tx = $cx + $tip * $s + 0.15 * $ww
    $global:g.Poly(@($tx, ($by - $hh), ($cx + 0.55 * $ww + 0.4 * $tip * $s), ($by - 0.62 * $hh), ($cx + $ww), ($by - 0.3 * $hh), $cx, $by, ($cx - $ww), ($by - 0.3 * $hh), ($cx - 0.5 * $ww + 0.4 * $tip * $s), ($by - 0.66 * $hh)), $l[1])
    $global:g.Ell($cx, ($by - 0.28 * $hh), $ww, (0.28 * $hh), $l[1])
  }
  $global:g.Ell($cx, ($by - 0.14 * $h), (0.2 * $w + 0.5), (0.14 * $h), $ramp[4])
}

# Particula que sube con progreso p (0..1) y color segun rampa [joven .. viejo]
function Pt([double]$x, [double]$y, [int]$size, $col) { $global:g.Rect([int][math]::Round($x), [int][math]::Round($y), $size, $size, $col) }

# ================= VFX DE AMBIENTE (frames animados) =================
$TAU = 2 * [math]::PI
$fireRamp = @($f0, $f1, $f2, $f3, $b3)
$iceRamp = @($c0, $c1, $c2, $WH, $WH)
$arcRamp = @($a0, $a2, $a3, $a4, $WH)

# ---------- llamas ----------
function TorchVfx([string]$name, $ramp, [string]$desc) {
  New-Vfx $name 32 48 8 8 'bucle' 16 46 $desc {
    param($f, $t)
    $ph = 2 * [math]::PI * $t; $cx = 16; $by = 46
    $hgt = 32 * (1 + 0.10 * [math]::Sin($ph * 2) + 0.05 * [math]::Sin($ph * 3 + 1))
    $wid = 11 * (1 + 0.06 * [math]::Sin($ph * 2 + 2))
    $tp = 3.5 * [math]::Sin($ph)
    FlameA ($cx - 6) $by 4 ($hgt * 0.5) (-2 * [math]::Sin($ph + 1)) $ramp
    FlameA ($cx + 6) $by 4 ($hgt * 0.45) (2 * [math]::Sin($ph + 2)) $ramp
    FlameA $cx $by $wid $hgt $tp $ramp
    for ($k = 0; $k -lt 3; $k++) {
      $p = ($t + $k / 3.0) % 1.0
      $ey = $by - $hgt * 0.7 - $p * 14; $ex = $cx + 5 * [math]::Sin(2 * [math]::PI * $p + $k * 2)
      $ec = $ramp[3]; if ($p -gt 0.4) { $ec = $ramp[2] }; if ($p -gt 0.75) { $ec = $ramp[1] }
      Pt $ex $ey 1 $ec
    }
  }
}
TorchVfx 'vfx_llama_antorcha' $fireRamp 'Llama de antorcha (base en el centro inferior; en prop_antorcha_pared la base esta en 50,38)'
