    $hh = $tg[2] * (1 + 0.14 * [math]::Sin($ph * 2 + $tg[3]))
    FlameA (36 + $tg[0]) 52 $tg[1] $hh (3 * [math]::Sin($ph + $tg[3])) $fireRamp
  }
