# ---------- particulas de ambiente ----------
New-Vfx 'vfx_chispas_ascendentes' 32 64 12 12 'bucle' 16 62 'Chispas y pavesas que suben y se apagan' {
  param($f, $t)
  $seeds = @(@(10,0.0,0.3), @(22,0.17,1.1), @(16,0.33,2.0), @(8,0.5,2.7), @(24,0.67,3.4), @(14,0.83,4.1))
