New-Vfx 'vfx_humo_ascendente' 40 72 12 6 'bucle' 20 70 'Columna de humo gris que sube, crece y se disuelve con tramado' {
  param($f, $t)
  $pl = 0..3 | ForEach-Object { [pscustomobject]@{ P = (($t + $_ / 4.0) % 1.0); K = $_ } } | Sort-Object P -Descending
  foreach ($q in $pl) {
    $p = $q.P; $r = 3 + 7 * $p
    $cy = 66 - $p * 58; $cx = 20 + 6 * [math]::Sin(2 * [math]::PI * $p * 1.2 + $q.K * 1.7)
    $mode = 0; if ($p -ge 0.5) { $mode = 1 }; if ($p -ge 0.75) { $mode = 2 }
    $c = $i4; if ($p -ge 0.35) { $c = $i3 }; if ($p -ge 0.7) { $c = $i2 }
    $g.EllD($cx, $cy, $r, $r * 0.85, $c, $mode)
    if ($p -lt 0.5) { $g.EllD($cx - $r * 0.3, $cy - $r * 0.3, $r * 0.4, $r * 0.35, $i5, 0) }
  }
}

New-Vfx 'vfx_polvo_flotante' 64 64 12 6 'bucle' 32 32 'Motas de polvo que titilan en un haz de luz' {
  param($f, $t)
  $rng = New-Object System.Random(5)
  for ($k = 0; $k -lt 14; $k++) {
    $x0 = $rng.Next(4, 60); $y0 = $rng.Next(4, 60)
    $p1 = $rng.NextDouble() * 6.283; $p2 = $rng.NextDouble() * 6.283; $p3 = $rng.NextDouble() * 6.283
    $ax = 2 + $rng.Next(4); $ay = 2 + $rng.Next(3)
    $x = $x0 + $ax * [math]::Sin(2 * [math]::PI * $t + $p1); $y = $y0 + $ay * [math]::Sin(2 * [math]::PI * $t + $p2)
    $v = [math]::Sin(4 * [math]::PI * $t + $p3)
    $c = $b0; if ($v -gt -0.5) { $c = $b2 }; if ($v -gt 0) { $c = $b3 }; if ($v -gt 0.6) { $c = $WH }
    $sz = 1; if (($k % 5) -eq 0) { $sz = 2 }
    Pt $x $y $sz $c
  }
}

# ---------- goteras ----------
function DripVfx([string]$name, $body, $hi, $sh, [string]$desc) {
  New-Vfx $name 16 56 12 8 'bucle' 8 54 $desc {
    param($f, $t)
    switch ($f) {
      0 { $g.Ell(8, 3, 1.6, 1.6, $body) }
      1 { $g.Ell(8, 4, 2, 2.6, $body) }
      2 { $g.Ell(8, 5, 2.2, 3.6, $body); $g.Set(7, 4, $hi) }
      3 { $g.Rect(8, 2, 1, 5, $body); $g.Ell(8, 10, 2.2, 2.2, $body); $g.Poly(@(8,6, 9.6,10, 6.4,10), $body); $g.Set(7, 9, $hi) }
      { $_ -ge 4 -and $_ -le 7 } {
        $cy = @(0, 0, 0, 0, 17, 25, 34, 44)[$f]
        $g.Ell(8, $cy + 1, 2.2, 2.2, $body); $g.Poly(@(8, ($cy - 5), 9.8, ($cy + 0.5), 6.2, ($cy + 0.5)), $body)
        $g.Set(7, $cy, $hi); $g.Set(9, $cy + 2, $sh)
      }
      8 { foreach ($p in @(@(8,52),@(6,53),@(10,53),@(7,51),@(9,51))) { $g.Set($p[0], $p[1], $body) }; $g.Set(8, 51, $hi) }
      9 { foreach ($p in @(@(3,52),@(13,52),@(5,49),@(11,49),@(8,47),@(4,50),@(12,50))) { $g.Set($p[0], $p[1], $body) }; $g.Set(8, 47, $hi); $g.Set(5, 49, $hi) }
      10 { foreach ($p in @(@(2,53),@(14,53),@(4,51),@(12,51),@(5,50))) { $g.Set($p[0], $p[1], $body) }; $g.Rect(5, 54, 7, 1, $sh) }
      11 { $g.Rect(4, 54, 9, 1, $sh); $g.Set(8, 53, $body) }
    }
  }
}
DripVfx 'vfx_gota_agua' $c1 $c2 $c0 'Gota de agua: se forma, cae y salpica (ciclo completo)'
DripVfx 'vfx_gota_sangre' $r1 $r2 $r0 'Gota de sangre: se forma, cae y salpica (ciclo completo)'

# ---------- brillos ----------
function SparkVfx([string]$name, $outer, $mid, [string]$desc) {
  New-Vfx $name 32 32 8 10 'bucle' 16 16 $desc {
    param($f, $t)
    $sz = @(0, 3, 6, 10, 13, 10, 6, 3)
    foreach ($sp in @(@(16, 16, $sz[$f]), @(7, 9, [int]($sz[($f + 4) % 8] / 3)), @(25, 24, [int]($sz[($f + 2) % 8] / 3)))) {
      $cx = $sp[0]; $cy = $sp[1]; $s = $sp[2]
      if ($s -le 0) { continue }
      for ($k = 1; $k -le $s; $k++) {
        $c = $outer; if ($k -le $s * 0.6) { $c = $mid }; if ($k -le 2) { $c = $WH }
        foreach ($d in @(@(1,0), @(-1,0), @(0,1), @(0,-1))) {
          $g.Set($cx + $d[0] * $k, $cy + $d[1] * $k, $c)
          if ($k -le $s / 3) { $g.Set($cx + $d[0] * $k + $d[1], $cy + $d[1] * $k + $d[0], $c) }
        }
      }
      $g.Rect($cx - 1, $cy - 1, 3, 3, $WH)
      if ($s -ge 8) { foreach ($k in 1,2,3) { foreach ($d in @(@(1,1),@(-1,1),@(1,-1),@(-1,-1))) { $g.Set($cx + $d[0] * $k, $cy + $d[1] * $k, $outer) } } }
    }
  }
}
SparkVfx 'vfx_brillo_cristal_arcano' $a3 $a4 'Destello en cruz sobre cristales arcanos'
SparkVfx 'vfx_brillo_cristal_hielo' $c1 $c2 'Destello en cruz sobre cristales de hielo'

# ---------- orbes ----------
function OrbVfx([string]$name, $ramp, [string]$desc) {
  New-Vfx $name 48 48 8 8 'bucle' 24 24 $desc {
    param($f, $t)
    $ph = 2 * [math]::PI * $t
    $r = 14 + [math]::Sin($ph); $inn = 9 + 1.2 * [math]::Sin($ph * 2)
    $g.EllD(24, 24, $r + 5, $r + 5, $ramp[0], 1)
    if ([math]::Sin($ph) -gt 0) { $g.EllD(24, 24, $r + 3, $r + 3, $ramp[1], 3) }
    $g.Ell(24, 24, $r, $r, $ramp[0]); $g.Ell(23, 23, $r - 1.5, $r - 1.5, $ramp[1])
    $g.Ell(21, 21, $inn, $inn, $ramp[2]); $g.Ell(19, 19, 4 + 0.8 * [math]::Sin($ph), 4 + 0.8 * [math]::Sin($ph), $ramp[3])
    $g.Set(17, 16, $WH); $g.Set(18, 16, $WH); $g.Set(17, 17, $WH)
    for ($k = 0; $k -lt 4; $k++) {
      $ang = $ph + $k * [math]::PI / 2
      Pt (24 + ($r + 6) * [math]::Cos($ang)) (24 + ($r + 6) * 0.6 * [math]::Sin($ang)) 2 $ramp[3]
    }
  }
}
OrbVfx 'vfx_orbe_arcano' @($a0, $a2, $a3, $a4) 'Orbe arcano que pulsa con cuatro particulas orbitando'
OrbVfx 'vfx_orbe_hielo' @($c0, $c1, $c2, $c2) 'Orbe de hielo que pulsa con cuatro particulas orbitando'
OrbVfx 'vfx_orbe_fuego' @($f1, $f2, $f3, $b3) 'Orbe de fuego que pulsa con cuatro particulas orbitando'

# ---------- circulo de runas ----------
New-Vfx 'vfx_circulo_runas' 64 64 8 8 'bucle' 32 32 'Circulo ritual con luz que recorre el anillo y los vertices (a juego con tile_suelo_runas)' {
  param($f, $t)
  $verts = @(@(32,13), @(49,43), @(15,43), @(32,51), @(15,21), @(49,21))
  $g.Ring(32, 32, 27, 27, 2, $a1); $g.Ring(32, 32, 20, 20, 1, $a1)
  $lc = $a1; if (($f % 2) -eq 0) { $lc = $a2 }
  $g.Line(32,13,49,43,$lc); $g.Line(49,43,15,43,$lc); $g.Line(15,43,32,13,$lc)
  $g.Line(32,51,15,21,$lc); $g.Line(15,21,49,21,$lc); $g.Line(49,21,32,51,$lc)
  $shift = [int][math]::Floor($f * 1.5); $act = [int][math]::Floor($f * 6 / 8)
  for ($i = 0; $i -lt 12; $i++) {
    $ang = 2 * [math]::PI * $i / 12; $px = [int][math]::Round(32 + 24 * [math]::Cos($ang)); $py = [int][math]::Round(32 + 24 * [math]::Sin($ang))
    $pos = ($i - $shift + 12) % 12
    if ($pos -eq 0) { $g.Rect($px - 1, $py - 1, 3, 3, $a4) } elseif ($pos -eq 1) { $g.Rect($px - 1, $py - 1, 2, 2, $a3) } elseif ($pos -eq 2) { $g.Set($px, $py, $a2) } else { $g.Set($px, $py, $a1) }
  }
  for ($v = 0; $v -lt 6; $v++) {
    $x = $verts[$v][0]; $y = $verts[$v][1]
    if ($v -eq $act) { $g.Rect($x - 1, $y - 1, 3, 3, $a3); $g.Set($x, $y, $a4) } else { $g.Set($x, $y, $a2) }
  }
  if (($f % 2) -eq 0) { $g.Rect(31, 31, 2, 2, $a3) } else { $g.Rect(31, 31, 2, 2, $a2) }
}

# ---------- niebla de suelo ----------
New-Vfx 'vfx_niebla_suelo' 96 28 12 4 'bucle' 48 26 'Niebla baja con tramado, en bucle sin costura horizontal' {
  param($f, $t)
  $ph = 2 * [math]::PI * $t
  $bl = @(@(10,20,22,6,0.0,1), @(40,18,28,7,1.0,1), @(75,21,24,6,2.0,1), @(25,23,30,5,3.1,1), @(60,22,26,5,4.2,1))
  foreach ($b in $bl) {
    $x = $b[0] + 9 * [math]::Sin($ph + $b[4]); $ry = $b[3] * (1 + 0.15 * [math]::Sin(2 * $ph + $b[4]))
    foreach ($ox in -96, 0, 96) {
      $g.EllD($x + $ox, $b[1], $b[2], $ry, $i3, 1)
      $g.EllD($x + $ox, $b[1] - 1, $b[2] * 0.6, $ry * 0.6, $i4, 3)
    }
  }
  $g.Rect(0, 25, 96, 3, 0)
}

# ---------- brasas ----------
New-Vfx 'vfx_brasas_pulso' 48 24 8 6 'bucle' 24 22 'Monton de ceniza con brasas que laten y dos chispas' {
  param($f, $t)
  $ph = 2 * [math]::PI * $t
  $g.Poly(@(2,22, 7,13, 18,9, 30,9, 41,13, 46,22), $o1)
  $g.Noise($o1, $o2, 12, 3); $g.Bevel($o1, $o2, $o0)
  $rng = New-Object System.Random(9)
