function OrbBody([double]$cx, [double]$cy, [double]$rad, $ramp) {
  $global:g.Ell($cx, $cy, $rad + 1, $rad + 1, $ramp[0])
  $global:g.Ell($cx, $cy, $rad, $rad, $ramp[1])
  $global:g.Ell($cx - $rad * 0.15, $cy - $rad * 0.15, $rad * 0.65, $rad * 0.65, $ramp[2])
  $global:g.Ell($cx - $rad * 0.3, $cy - $rad * 0.3, $rad * 0.35, $rad * 0.35, $ramp[3])
  $global:g.Set([int]($cx - $rad * 0.4), [int]($cy - $rad * 0.4), $ramp[4])
}

# ---------- proyectil con estela (viaja hacia la derecha) ----------
function BoltVfx([string]$name, $ramp, [string]$desc) {
  New-Vfx $name 56 24 6 12 'bucle' 46 12 $desc {
    param($f, $t)
    $ph = 2 * [math]::PI * $t; $rr = 5 + 0.8 * [math]::Sin($ph)
    for ($i = 9; $i -ge 1; $i--) {
      $tx = 46 - $i * 4.6; $tr = [math]::Max(1, $rr * (1 - $i / 10.0)); $ty = 12 + 1.6 * [math]::Sin($ph + $i * 0.9)
      $mode = 0; if ($i -ge 4) { $mode = 1 }; if ($i -ge 7) { $mode = 3 }
      $col = $ramp[1]; if ($i -ge 3) { $col = $ramp[0] }
      $g.EllD($tx, $ty, $tr + 1, $tr, $col, $mode)
    }
    $rng = New-Object System.Random($f * 7 + 3)
    for ($k = 0; $k -lt 4; $k++) { Pt (38 - $rng.Next(0, 34)) (12 + $rng.Next(-7, 8)) 1 $ramp[2] }
    OrbBody 46 12 $rr $ramp
  }
}

# ---------- impacto / explosion (una vez) ----------
function ImpactVfx([string]$name, $ramp, [string]$desc) {
  New-Vfx $name 64 64 8 14 'una vez' 32 32 $desc {
    param($f, $t)
    $cx = 32; $cy = 32; $rr = 4 + $f * 3.5; $th = [math]::Max(1, 4 - [math]::Floor($f / 2))
    $rc = $ramp[3]; if ($f -ge 2) { $rc = $ramp[2] }; if ($f -ge 4) { $rc = $ramp[1] }; if ($f -ge 6) { $rc = $ramp[0] }
    if ($f -ge 1 -and $f -le 6) { $g.Ring($cx, $cy, $rr, $rr, $th, $rc) }
    if ($f -le 3) {
      for ($k = 0; $k -lt 8; $k++) {
        $ang = $k * [math]::PI / 4 + 0.2; $r1 = $rr * 0.45; $r2 = $rr * 0.95 + 3
        $g.Line([int]($cx + $r1 * [math]::Cos($ang)), [int]($cy + $r1 * [math]::Sin($ang)), [int]($cx + $r2 * [math]::Cos($ang)), [int]($cy + $r2 * [math]::Sin($ang)), $ramp[2])
      }
    }
    if ($f -le 2) { $fr = 6 + $f * 3; $g.Ell($cx, $cy, $fr, $fr, $ramp[3]); $g.Ell($cx, $cy, $fr * 0.6, $fr * 0.6, $ramp[4]) }
    $rng = New-Object System.Random(3)
    for ($k = 0; $k -lt 10; $k++) {
      $a = $rng.NextDouble() * 6.283; $d = 0.7 + $rng.NextDouble() * 0.4
      if ($f -ge 2 -and $k -lt (11 - $f)) {
        $pr = [math]::Min(30, $rr * $d + 2)
        $sc = $ramp[3]; if (($k % 2) -eq 1) { $sc = $ramp[1] }
        Pt ($cx + $pr * [math]::Cos($a)) ($cy + $pr * [math]::Sin($a)) 1 $sc
      }
    }
  }
}

