function BeamVfx([string]$name, $ramp, [string]$desc) {
  New-Vfx $name 64 16 6 14 'bucle' 0 8 $desc {
    param($f, $t)
    for ($x = 0; $x -lt 64; $x++) {
      $am = [math]::Sin(2 * [math]::PI * ($x / 64.0 * 2 + $t))
      $ho = [int][math]::Round(5 + 1.4 * $am); $hm = [int][math]::Round(3.2 + 0.9 * $am); $hi = [int][math]::Round(2 + 0.5 * $am)
      $g.Rect($x, 8 - $ho, 1, 2 * $ho, $ramp[1]); $g.Rect($x, 8 - $hm, 1, 2 * $hm, $ramp[2]); $g.Rect($x, 8 - $hi, 1, 2 * $hi, $ramp[3])
      $g.Rect($x, 7, 1, 2, $ramp[4])
      if ((($x + $f) % 2) -eq 0) { $g.Set($x, 8 - $ho - 1, $ramp[0]); $g.Set($x, 8 + $ho, $ramp[0]) }
    }
    $rng = New-Object System.Random($f * 5 + 1)
    for ($k = 0; $k -lt 3; $k++) { Pt ($rng.Next(0, 64)) (8 + $rng.Next(-7, 7)) 1 $ramp[3] }
  }
}

