function PillarVfx([string]$name, $ramp, [string]$desc) {
  New-Vfx $name 40 96 8 8 'bucle' 20 94 $desc {
    param($f, $t)
    $g.EllD(20, 92, 16, 5, $ramp[0], 1)
    for ($y = 0; $y -lt 92; $y++) {
      for ($x = 8; $x -lt 32; $x++) {
        if ($y -lt 8 -and -not ((($x % 2) -eq 0) -and (($y % 2) -eq 0))) { continue }
        if ($y -ge 8 -and $y -lt 18 -and -not ((($x + $y) % 2) -eq 0)) { continue }
        $dx = [math]::Abs($x - 19.5) / 11.5
        $v = ([math]::Sin(2 * [math]::PI * ($y / 24.0 + $t) + $x * 0.5) + 1) / 2
        if ($dx -gt 0.8 -and $v -lt 0.4) { continue }
        $col = $ramp[3]; if ($dx -gt 0.45) { $col = $ramp[2] }; if ($dx -gt 0.8) { $col = $ramp[1] }
        if ($v -gt 0.88 -and $dx -le 0.8) { $col = $ramp[4] }
        $g.Set($x, $y, $col)
      }
    }
    $g.Ring(20, 92, 15, 4, 2, $ramp[2])
    for ($k = 0; $k -lt 5; $k++) {
      $p = ($t + $k / 5.0) % 1.0
      Pt (20 + ($k - 2) * 4 + 2 * [math]::Sin(2 * [math]::PI * $p + $k)) (88 - $p * 80) 1 $ramp[3]
    }
  }
}

