# ---------- proyectil cayendo en diagonal (bucle, atraviesa el lienzo) ----------
function FallVfx([string]$name, $ramp, [string]$shape, [string]$desc) {
  New-Vfx $name 64 64 8 12 'bucle' 32 32 $desc {
    param($f, $t)
    $hx = 66 - 72 * $t; $hy = -6 + 72 * $t
    for ($i = 9; $i -ge 1; $i--) {
      $tr = [math]::Max(1, 5 * (1 - $i / 10.0))
      $mode = 0; if ($i -ge 4) { $mode = 1 }; if ($i -ge 7) { $mode = 3 }
      $col = $ramp[1]; if ($i -ge 3) { $col = $ramp[0] }
      $g.EllD($hx + 3.6 * $i, $hy - 3.6 * $i, $tr + 1, $tr, $col, $mode)
    }
    if ($shape -eq 'shard') {
      $dx = -0.7071; $dy = 0.7071; $nx = 0.7071; $ny = 0.7071
      $g.Poly(@(($hx + $dx * 11), ($hy + $dy * 11), ($hx - $dx * 4 + $nx * 4), ($hy - $dy * 4 + $ny * 4), ($hx - $dx * 4 - $nx * 4), ($hy - $dy * 4 - $ny * 4)), $ramp[1])
      $g.Poly(@(($hx + $dx * 8), ($hy + $dy * 8), ($hx + $nx * 1.6), ($hy + $ny * 1.6), ($hx - $nx * 1.6), ($hy - $ny * 1.6)), $ramp[2])
      $g.Line([int]($hx), [int]($hy), [int]($hx + $dx * 9), [int]($hy + $dy * 9), $ramp[3]); $g.Set([int]($hx + $dx * 10), [int]($hy + $dy * 10), $ramp[4])
    } else { OrbBody $hx $hy 5.5 $ramp }
  }
}

# ---------- orbes orbitando (bucle) ----------
function OrbitVfx([string]$name, $ramp, [string]$desc) {
  New-Vfx $name 64 64 8 10 'bucle' 32 32 $desc {
    param($f, $t)
    $g.EllD(32, 32, 7, 7, $ramp[0], 1); $g.Ell(32, 32, 2.5, 2.5, $ramp[2]); $g.Set(32, 32, $ramp[4])
    $orbs = 0..2 | ForEach-Object { $ang = 2 * [math]::PI * $t + $_ * 2 * [math]::PI / 3; [pscustomobject]@{ A = $ang; Z = [math]::Sin($ang) } } | Sort-Object Z
    foreach ($o in $orbs) {
      for ($i = 4; $i -ge 1; $i--) {
        $ta = $o.A - 0.3 * $i
        Pt (32 + 24 * [math]::Cos($ta)) (32 + 10 * [math]::Sin($ta)) 1 $(if ($i -ge 3) { $ramp[0] } else { $ramp[1] })
      }
      $rad = 3; if ($o.Z -gt 0) { $rad = 4.5 }
      OrbBody (32 + 24 * [math]::Cos($o.A)) (32 + 10 * $o.Z) $rad $ramp
    }
  }
}

# ---------- corte en arco (una vez) ----------
function SlashVfx([string]$name, $ramp, [string]$desc) {
  New-Vfx $name 64 64 6 16 'una vez' 32 38 $desc {
    param($f, $t)
    $ahA = @(0.3, 0.6, 0.85, 1, 1, 1); $atA = @(0, 0, 0.05, 0.3, 0.6, 0.85)
    $s0 = -150; $s1 = 30; $ah = $s0 + ($s1 - $s0) * $ahA[$f]; $at = $s0 + ($s1 - $s0) * $atA[$f]
    if ($ah -gt $at) {
      for ($y = 0; $y -lt 64; $y++) {
        for ($x = 0; $x -lt 64; $x++) {
          if ($f -eq 4 -and (($x + $y) % 2) -eq 1) { continue }
          if ($f -eq 5 -and -not ((($x % 2) -eq 0) -and (($y % 2) -eq 0))) { continue }
          $dx = $x + 0.5 - 32; $dy = $y + 0.5 - 38; $dist = [math]::Sqrt($dx * $dx + $dy * $dy)
          if ($dist -gt 26) { continue }
          $th = [math]::Atan2($dy, $dx) * 180 / [math]::PI
          if ($th -lt $at -or $th -gt $ah) { continue }
          $u = ($th - $at) / ($ah - $at); $wd = 1 + 9 * [math]::Sin([math]::PI * $u)
          if ($dist -lt (26 - $wd)) { continue }
          $s = (26 - $dist) / $wd
          $col = $ramp[1]; if ($s -lt 0.8) { $col = $ramp[2] }; if ($s -lt 0.5) { $col = $ramp[3] }; if ($s -lt 0.2) { $col = $ramp[4] }
          $g.Set($x, $y, $col)
        }
      }
    }
  }
}

# ---------- brote desde el suelo: pinchos, cristales o llamaradas (una vez) ----------
function SpikesVfx([string]$name, $ramp, [string]$shape, [string]$desc) {
  New-Vfx $name 64 64 8 12 'una vez' 32 60 $desc {
    param($f, $t)
    $g.EllD(32, 60, 28, 5, $ramp[0], 1)
    $sx = @(12, 22, 32, 42, 52); $sh = @(20, 30, 44, 30, 20); $sw = @(5, 6, 7, 6, 5); $dl = @(2, 1, 0, 1, 2)
    foreach ($i in 0, 4, 1, 3, 2) {
      $gr = [math]::Min(($f - $dl[$i] + 1) / 3.0, (8 - $f) / 2.0); $gr = [math]::Max(0, [math]::Min(1, $gr))
      if ($gr -le 0) { continue }
      $hc = $sh[$i] * $gr; $x = $sx[$i]; $hw = $sw[$i]
      if ($shape -eq 'flame') { FlameA $x 60 ($hw + 1) $hc (2 * [math]::Sin($f + $i)) $ramp }
      else {
        $g.Poly(@(($x - $hw), 60, $x, (60 - $hc), ($x + $hw), 60), $ramp[1])
        $g.Poly(@(($x - $hw), 60, $x, (60 - $hc), $x, 60), $ramp[2])
        $g.Line([int]($x - $hw + 1), 59, $x, [int](60 - $hc + 2), $ramp[3]); $g.Set($x, [int](60 - $hc), $ramp[4])
      }
    }
  }
}

