# ---------- curacion sagrada (bucle) ----------
New-Vfx 'vfx_curacion_sagrada' 48 64 8 8 'bucle' 24 60 'Curacion sagrada: cruces de luz dorada que ascienden desde un circulo' {
  param($f, $t)
  $ramp = $magSac
  $g.EllD(24, 58, 18, 5, $ramp[0], 1)
  for ($y = 14; $y -lt 54; $y++) { for ($x = 12; $x -lt 36; $x++) { if ((($x + $y) % 2) -eq 0 -and ((($x * 7 + $y * 13) % 10) / 10.0) -lt (($y - 14) / 42.0)) { $g.Set($x, $y, $ramp[0]) } } }
  $g.Ring(24, 58, 16 + 2 * [math]::Sin(2 * [math]::PI * $t), 4, 1, $ramp[2])
  for ($k = 0; $k -lt 6; $k++) {
    $p = ($t + $k / 6.0) % 1.0; $x = [int][math]::Round(24 + ($k - 2.5) * 5 + 2 * [math]::Sin(2 * [math]::PI * $p + $k)); $y = [int][math]::Round(56 - $p * 48)
    if ($p -lt 0.7) {
      $c = $ramp[2]; if ($p -gt 0.25) { $c = $ramp[3] }
      $g.Set($x, $y, $ramp[4]); foreach ($d in @(@(1,0), @(-1,0), @(0,1), @(0,-1))) { $g.Set($x + $d[0], $y + $d[1], $c) }
    } else { $g.Set($x, $y, $ramp[1]) }
  }
}

# ---------- maldicion de sangre (bucle) ----------
New-Vfx 'vfx_maldicion_sangre' 48 64 8 8 'bucle' 24 60 'Maldicion: circulo rojo con luz que corre, niebla de sangre ascendente y gotas' {
  param($f, $t)
  $ramp = $magBlood
  $g.EllD(24, 58, 18, 5, $ramp[0], 1)
  $shift = [int][math]::Floor($f * 1.5)
  for ($i = 0; $i -lt 12; $i++) {
    $ang = 2 * [math]::PI * $i / 12; $px = [int][math]::Round(24 + 16 * [math]::Cos($ang)); $py = [int][math]::Round(58 + 4.5 * [math]::Sin($ang))
    $pos = ($i - $shift + 12) % 12
    if ($pos -eq 0) { $g.Rect($px - 1, $py, 3, 1, $ramp[3]) } elseif ($pos -eq 1) { $g.Rect($px - 1, $py, 2, 1, $ramp[2]) } elseif ($pos -eq 2) { $g.Set($px, $py, $ramp[1]) } else { $g.Set($px, $py, $ramp[0]) }
  }
  $pl = 0..2 | ForEach-Object { [pscustomobject]@{ P = (($t + $_ / 3.0) % 1.0); K = $_ } } | Sort-Object P -Descending
  foreach ($q in $pl) {
    $p = $q.P; $md = 0; if ($p -ge 0.5) { $md = 1 }
    $c = $ramp[1]; if ($p -ge 0.5) { $c = $ramp[0] }
    $g.EllD(24 + 4 * [math]::Sin(2 * [math]::PI * $p + $q.K * 2), 52 - $p * 40, 3 + 4 * $p, 3 + 4 * $p, $c, $md)
  }
  for ($k = 0; $k -lt 4; $k++) {
    $p = ($t + $k / 4.0) % 1.0; $x = 24 + ($k - 1.5) * 6; $y = 8 + $p * $p * 44
    $g.Rect([int][math]::Round($x), [int][math]::Round($y), 1, 2, $ramp[2]); $g.Set([int][math]::Round($x), [int][math]::Round($y), $ramp[3])
  }
}

