# ---------- congelacion: cristales que brotan alrededor (una vez) ----------
New-Vfx 'vfx_congelacion' 64 64 8 12 'una vez' 32 32 'Congelacion: cristales de hielo brotan en estrella sobre el objetivo y centellean' {
  param($f, $t)
  $ramp = $magIce
  $g.Ell(32, 33, 9, 7, $ramp[0]); $g.Ell(31, 32, 7, 5, $ramp[1]); $g.Ell(30, 31, 4, 3, $ramp[2])
  for ($k = 0; $k -lt 10; $k++) {
    $ang = $k * 2 * [math]::PI / 10 + 0.3
    $lmax = 26; if (($k % 2) -eq 1) { $lmax = 17 }
    $L = [math]::Min($lmax, 4 + ($f + 1) * 4.2 - ($k % 3))
    if ($L -le 6) { continue }
    $cs = [math]::Cos($ang); $sn = [math]::Sin($ang); $nx = -$sn; $ny = $cs
    $g.Poly(@((32 + $cs * 6 + $nx * 3), (32 + $sn * 6 + $ny * 3), (32 + $cs * $L), (32 + $sn * $L), (32 + $cs * 6 - $nx * 3), (32 + $sn * 6 - $ny * 3)), $ramp[1])
    $g.Line([int](32 + $cs * 7), [int](32 + $sn * 7), [int](32 + $cs * ($L - 2)), [int](32 + $sn * ($L - 2)), $ramp[2])
    $g.Set([int](32 + $cs * $L), [int](32 + $sn * $L), $ramp[4])
