  if ($f -ge 5) {
    $rng = New-Object System.Random($f)
    for ($k = 0; $k -lt 4; $k++) { $px = 32 + $rng.Next(-24, 24); $py = 32 + $rng.Next(-24, 24); Pt $px $py 1 $ramp[4]; Pt ($px + 1) $py 1 $ramp[3]; Pt ($px - 1) $py 1 $ramp[3] }
