# ================= BOLA DE FUEGO Y MURO DE FUEGO POR TAMANOS =================
# Tamanos: pequena, mediana, grande, enorme, colosal
$szNames = @('pequena', 'mediana', 'grande', 'enorme', 'colosal')

# ---------- bola de fuego en vuelo (bucle), hacia la derecha. R = radio de la cabeza ----------
function FireballVfx([string]$name, [double]$R, [string]$desc) {
  $cw = [int][math]::Ceiling($R * 10); $ch = [int][math]::Ceiling($R * 4.4); if (($ch % 2) -eq 1) { $ch++ }
  $hx = [int][math]::Round($cw - $R * 1.8); $cy = [int]($ch / 2)
  New-Vfx $name $cw $ch 8 12 'bucle' $hx $cy $desc {
    param($f, $t)
    $ramp = $magFire; $ph = 2 * [math]::PI * $t; $NT = 10
    for ($i = $NT; $i -ge 1; $i--) {
      $tx = $hx - $R * 0.68 * $i; $ty = $cy + $R * 0.3 * [math]::Sin($ph + $i * 0.9) * (0.4 + $i / $NT)
      $tr = $R * (1 - $i / ($NT + 1.0)) + 0.5
      $m1 = 0; if ($i -ge 5) { $m1 = 1 }; if ($i -ge 8) { $m1 = 3 }
      $g.EllD($tx, $ty, $tr * 1.1 + 0.5, $tr * 0.95, $ramp[0], $m1)
      if ($i -le 8) { $m2 = 0; if ($i -ge 6) { $m2 = 1 }; $g.EllD($tx + $R * 0.05, $ty, $tr * 0.78, $tr * 0.66, $ramp[1], $m2) }
      if ($i -le 6) { $g.EllD($tx + $R * 0.1, $ty, $tr * 0.5, $tr * 0.42, $ramp[2], 0) }
    }
    $rng = New-Object System.Random($f * 11 + 5); $esz = [int][math]::Max(1, [math]::Round($R / 14))
    for ($k = 0; $k -lt (5 + [int]($R / 3)); $k++) {
      $ex = $hx - $R * (1.4 + $rng.NextDouble() * 7); $ey = $cy + ($rng.NextDouble() - 0.5) * $R * 2.3
      $ec = $ramp[3]; if (($k % 2) -eq 1) { $ec = $ramp[2] }
      Pt $ex $ey $esz $ec
    }
    $fb = $R * 1.15 * (1 + 0.03 * [math]::Sin($ph))
    foreach ($lb in @(@(1.0, $ramp[0]), @(0.78, $ramp[1]), @(0.55, $ramp[2]), @(0.32, $ramp[3]))) {
      $sc2 = $lb[0]
      $g.Ell($hx, $cy, $fb * 0.62 * $sc2, $fb * 0.62 * $sc2, $lb[1])
      for ($k = 0; $k -lt 7; $k++) {
        $la = $k * 2 * [math]::PI / 7 + 0.4
        $lr = $fb * (0.30 + 0.06 * [math]::Sin($ph + $k * 1.3)) * $sc2 + 0.5
        $g.Ell($hx + [math]::Cos($la) * $fb * 0.58 * $sc2, $cy + [math]::Sin($la) * $fb * 0.58 * $sc2, $lr, $lr, $lb[1])
      }
    }
    $g.Ell($hx - $fb * 0.1, $cy - $fb * 0.1, $fb * 0.16, $fb * 0.16, $ramp[4])
  }
}

# ---------- explosion de bola de fuego (una vez), escalada por S ----------
function ExplodeVfx([string]$name, [double]$S, [string]$desc) {
  $cs = [int]([math]::Round(96 * $S / 2) * 2); $mid = [int]($cs / 2)
  New-Vfx $name $cs $cs 10 12 'una vez' $mid $mid $desc {
    param($f, $t)
    $ramp = $magFire; $fb = @(8, 16, 26, 32, 34, 32, 28, 22, 14, 6)[$f] * $S
    $limit = $mid - 2
    if ($f -ge 3) {
      $sm = (12 + ($f - 3) * 5) * $S; $md = 0; if ($f -ge 7) { $md = 1 }; if ($f -ge 9) { $md = 2 }
      $g.EllD($mid - 14 * $S, $mid - (8 + ($f - 3) * 2) * $S, $sm * 0.6, $sm * 0.55, $i3, $md)
      $g.EllD($mid + 14 * $S, $mid - (10 + ($f - 3) * 2) * $S, $sm * 0.6, $sm * 0.55, $i3, $md)
      $g.EllD($mid, $mid - (14 + ($f - 3) * 3) * $S, $sm * 0.7, $sm * 0.6, $i4, $md)
    }
    if ($f -ge 1 -and $f -le 6) {
      $rg = (12 + $f * 6.5) * $S; $th = [math]::Max(1, [math]::Round((4 - [math]::Floor($f / 2)) * $S * 0.8))
      $g.Ring($mid, $mid, $rg, $rg, $th, $ramp[2])
    }
    $fm1 = 0; if ($f -ge 7) { $fm1 = 1 }
    $nl = 7; if ($S -ge 1.5) { $nl = 11 }
    foreach ($lb in @(@(1.0, $ramp[0], $fm1), @(0.78, $ramp[1], $fm1), @(0.55, $ramp[2], 0), @(0.32, $ramp[3], 0))) {
      $sc2 = $lb[0]
      $g.EllD($mid, $mid, $fb * 0.62 * $sc2, $fb * 0.62 * $sc2, $lb[1], $lb[2])
      for ($k = 0; $k -lt $nl; $k++) {
        $la = $k * 2 * [math]::PI / $nl + 0.4 + 0.15 * $sc2 * [math]::Sin($k * 1.9)
        $lr = $fb * (0.30 + 0.07 * [math]::Sin($k * 2.7 + 1) - 0.01 * ($nl - 7)) * $sc2 + 0.5
        $g.EllD($mid + [math]::Cos($la) * $fb * 0.58 * $sc2, $mid + [math]::Sin($la) * $fb * 0.58 * $sc2 - $fb * 0.06 * (1 - $sc2), $lr, $lr, $lb[1], $lb[2])
      }
    }
    if ($f -le 3) { $g.Ell($mid, $mid, $fb * 0.15, $fb * 0.15, $ramp[4]) }
    $rng = New-Object System.Random(4); $nsp = 14 + [int](6 * $S); $psz = [int][math]::Max(1, [math]::Round($S * 0.8))
    for ($k = 0; $k -lt $nsp; $k++) {
      $a = $rng.NextDouble() * 6.283; $d = 1.05 + $rng.NextDouble() * 0.45; $rd = [math]::Min($limit, ($fb + 4 * $S) * $d)
      if ($f -ge 2 -and $k -lt ($nsp - 2 * $f)) { $pc = $ramp[1]; if (($k % 2) -eq 0) { $pc = $ramp[3] }; Pt ($mid + $rd * [math]::Cos($a)) ($mid + $rd * [math]::Sin($a)) $psz $pc }
    }
  }
}

# ---------- muro de fuego ----------
# Dibuja el muro con $Wc de ancho, base en $by y altura base $Hf. $gr escala la altura (0..1). Repetible en horizontal.
function WallDraw([double]$Wc, [double]$by, [double]$Hf, [double]$t, [double]$gr) {
  $ph = 2 * [math]::PI * $t
  $n = [int][math]::Max(3, [math]::Round($Wc / ($Hf * 0.5))); $sp = $Wc / $n
  $rampB = @($f0, $f1, $f1, $f2, $f3); $rampF = @($f0, $f1, $f2, $f3, $b3)
  if ($gr -gt 0.02) {
    for ($i = 0; $i -lt $n; $i++) {
      $fr = ($i * 0.618) % 1.0
      $hg = $Hf * (0.85 + 0.3 * $fr) * $gr * (1 + 0.12 * [math]::Sin(2 * $ph + $i * 1.3))
      foreach ($ox in (-$Wc), 0, $Wc) { FlameA ($i * $sp + $ox) $by ($sp * 0.55) $hg ($Hf * 0.05 * [math]::Sin($ph + $i * 1.1)) $rampB }
    }
    for ($i = 0; $i -lt $n; $i++) {
      $fr = (($i + 3) * 0.382) % 1.0
      $hg = $Hf * (0.55 + 0.3 * $fr) * $gr * (1 + 0.15 * [math]::Sin(2 * $ph + $i * 2.1 + 1))
      foreach ($ox in (-$Wc), 0, $Wc) { FlameA (($i + 0.5) * $sp + $ox) $by ($sp * 0.62) $hg ($Hf * 0.06 * [math]::Sin($ph + $i * 0.9 + 2)) $rampF }
    }
  }
  $esz = [int][math]::Max(1, [math]::Round($Hf / 60))
  for ($k = 0; $k -lt (2 * $n); $k++) {
    $p = ($t + ($k * 0.37) % 1.0) % 1.0
    $ex = ($k + 0.5) * ($Wc / (2 * $n)) + $Hf * 0.08 * [math]::Sin(2 * [math]::PI * $p + $k)
    $ey = $by - $Hf * 0.5 * $gr - $p * $Hf * 0.85 * [math]::Max($gr, 0.35)
    $ec = $f3; if ($p -gt 0.4) { $ec = $f2 }; if ($p -gt 0.75) { $ec = $f1 }
    Pt $ex $ey $esz $ec
  }
}

