# ---------- utilidades ----------
function ThickLine([double]$x1, [double]$y1, [double]$x2, [double]$y2, [double]$wd, $col) {
  $dx = $x2 - $x1; $dy = $y2 - $y1; $len = [math]::Sqrt($dx * $dx + $dy * $dy)
  if ($len -lt 0.01) { return }
  $nx = -$dy / $len; $ny = $dx / $len
  for ($o = -$wd / 2.0; $o -le $wd / 2.0 + 0.01; $o += 0.5) {
    $global:g.Line([int][math]::Round($x1 + $nx * $o), [int][math]::Round($y1 + $ny * $o), [int][math]::Round($x2 + $nx * $o), [int][math]::Round($y2 + $ny * $o), $col)
  }
}

function BoltPts([double]$ax, [double]$ay, [double]$bx, [double]$by, [int]$n, [double]$a0, [double]$a1, $rng) {
  $dx = $bx - $ax; $dy = $by - $ay; $len = [math]::Sqrt($dx * $dx + $dy * $dy); $nx = -$dy / $len; $ny = $dx / $len
  $pts = @(); $sg = 1
  for ($i = 0; $i -le $n; $i++) {
    $u = $i / [double]$n; $amp = $a0 + ($a1 - $a0) * $u; $off = 0
    if ($i -gt 0 -and $i -lt $n) { if ($rng.NextDouble() -lt 0.75) { $sg = -$sg }; $off = $sg * $amp * (0.35 + 0.65 * $rng.NextDouble()) }
    $pts += , @(($ax + $dx * $u + $nx * $off), ($ay + $dy * $u + $ny * $off))
  }
  return , $pts
}

# style 0 = completo, 1 = fino (apagandose), 2 = solo nucleo discontinuo
function DrawBolt($pts, [double]$w0, [double]$w1, $ramp, [double]$upto, [int]$style) {
  $n = $pts.Count - 1
  $layers = @(@(6, 0), @(3, 1), @(0, 2), @(-1, 4))
  if ($style -eq 1) { $layers = @(@(2, 1), @(0, 2), @(-1, 4)) }
  if ($style -eq 2) { $layers = @(@(-1, 2)) }
  foreach ($ly in $layers) {
    for ($i = 0; $i -lt $n; $i++) {
      $u = $i / [double]$n; if ($u -ge $upto) { break }
      if ($style -eq 2 -and ($i % 2) -eq 1) { continue }
      $wd = $w0 + ($w1 - $w0) * $u
      if ($ly[0] -lt 0) { $wl = [math]::Max(1, [math]::Round($wd * 0.35)) } else { $wl = $wd + $ly[0] }
      ThickLine $pts[$i][0] $pts[$i][1] $pts[$i + 1][0] $pts[$i + 1][1] $wl $ramp[$ly[1]]
      $global:g.Ell($pts[$i + 1][0], $pts[$i + 1][1], $wl / 2.0, $wl / 2.0, $ramp[$ly[1]])
    }
  }
}

function DrawFork([double]$sx, [double]$sy, [double]$ang, [double]$len, [int]$segs, $rng, $ramp, [double]$wd) {
  $pp = New-Object System.Collections.ArrayList; [void]$pp.Add(@($sx, $sy))
  $px = $sx; $py = $sy; $a = $ang
  for ($i = 0; $i -lt $segs; $i++) {
    $a += ($rng.NextDouble() - 0.5) * 1.1
    $px += [math]::Cos($a) * $len / $segs; $py += [math]::Sin($a) * $len / $segs
    [void]$pp.Add(@($px, $py))
  }
  foreach ($ly in @(@(2, 1), @(0, 2), @(-1, 4))) {
    for ($i = 0; $i -lt $segs; $i++) {
      $wl = $wd + $ly[0]; if ($ly[0] -lt 0) { $wl = 1 }
      ThickLine $pp[$i][0] $pp[$i][1] $pp[$i + 1][0] $pp[$i + 1][1] $wl $ramp[$ly[1]]
    }
  }
}

# Bola de fuego vista de frente (billboard que se aleja): corona de lenguas en espiral + cuerpo lobulado
function HeadOnFire([double]$cx, [double]$cy, [double]$D, [double]$t) {
  $ramp = $magFire; $R = $D * 0.26; $ph = 2 * [math]::PI * $t
  $N = [int][math]::Max(4, [math]::Min(11, [math]::Round($D / 14) + 4))
  for ($k = 0; $k -lt $N; $k++) {
    $ang = 2 * [math]::PI * $k / $N
    $len = $R * (1.45 + 0.3 * [math]::Sin($ph + $k * 1.7) + 0.1 * [math]::Sin(2 * $ph + $k * 0.9))
    foreach ($ly in @(@(1.0, 0), @(0.78, 1), @(0.56, 2))) {
      $s = $ly[0]; $bw = 0.3 * $s + 0.08; $tl = $R * 0.7 + ($len - $R * 0.7) * $s
      $global:g.Poly(@(($cx + [math]::Cos($ang - $bw) * $R * 0.7), ($cy + [math]::Sin($ang - $bw) * $R * 0.7), ($cx + [math]::Cos($ang + 0.5) * $tl), ($cy + [math]::Sin($ang + 0.5) * $tl), ($cx + [math]::Cos($ang + $bw) * $R * 0.7), ($cy + [math]::Sin($ang + $bw) * $R * 0.7)), $ramp[$ly[1]])
    }
  }
  $fb = $R * 1.12
  foreach ($lb in @(@(1.0, $ramp[0]), @(0.78, $ramp[1]), @(0.55, $ramp[2]), @(0.32, $ramp[3]))) {
    $sc2 = $lb[0]
    $global:g.Ell($cx, $cy, $fb * 0.62 * $sc2, $fb * 0.62 * $sc2, $lb[1])
    for ($k = 0; $k -lt 7; $k++) {
      $la = $k * 2 * [math]::PI / 7 + 0.4
      $lr = $fb * (0.30 + 0.06 * [math]::Sin($ph + $k * 1.3)) * $sc2 + 0.5
      $global:g.Ell($cx + [math]::Cos($la) * $fb * 0.58 * $sc2, $cy + [math]::Sin($la) * $fb * 0.58 * $sc2, $lr, $lr, $lb[1])
    }
  }
  $global:g.Ell($cx - $fb * 0.1, $cy - $fb * 0.1, [math]::Max(0.6, $fb * 0.16), [math]::Max(0.6, $fb * 0.16), $ramp[4])
}

