function LightningSet([string]$sfx, $ramp, [string]$label) {
  # Cinta repetible (se estira entre baston y mira con la malla o el componente de cinta del motor)
  New-Vfx "vfx_fp_relampago_haz_$sfx" 256 48 8 14 'bucle' 0 24 "Relampago $label como cinta repetible en horizontal (256x48): trazo principal, hebra secundaria, ramificaciones y chispas" {
    param($f, $t)
    $rng = New-Object System.Random($f * 31 + 7)
    $pts = @(); $sg = 1
    for ($i = 0; $i -le 32; $i++) {
      $win = [math]::Sqrt([math]::Sin([math]::PI * $i / 32.0)); $off = 0
      if ($i -gt 0 -and $i -lt 32) { if ($rng.NextDouble() -lt 0.75) { $sg = -$sg }; $off = $sg * (3 + $rng.NextDouble() * 8) * $win }
      $pts += , @(($i * 8.0), (24 + $off))
    }
    DrawBolt $pts 3 3 $ramp 1.01 0
    $pts2 = @(); $sg = -1
    for ($i = 0; $i -le 32; $i++) {
      $win = [math]::Sqrt([math]::Sin([math]::PI * $i / 32.0)); $off = 0
      if ($i -gt 0 -and $i -lt 32) { if ($rng.NextDouble() -lt 0.6) { $sg = -$sg }; $off = $sg * (2 + $rng.NextDouble() * 6) * $win }
      $pts2 += , @(($i * 8.0), (24 + $off))
    }
    for ($i = 0; $i -lt 32; $i++) { ThickLine $pts2[$i][0] $pts2[$i][1] $pts2[$i + 1][0] $pts2[$i + 1][1] 1 $ramp[2] }
    for ($k = 0; $k -lt 4; $k++) {
      $si = $rng.Next(4, 28); $dirA = 0; if ($rng.NextDouble() -lt 0.5) { $dirA = [math]::PI }
      DrawFork $pts[$si][0] $pts[$si][1] ($dirA + ($rng.NextDouble() - 0.5) * 1.6) 24 3 $rng $ramp 1
    }
    for ($k = 0; $k -lt 8; $k++) { Pt ($rng.Next(0, 256)) (24 + $rng.Next(-16, 17)) 1 $(if (($k % 2) -eq 0) { $ramp[2] } else { $ramp[4] }) }
  }

  # Recorrido en pantalla (480x270) en tres fases: inicio, bucle y fin
  foreach ($ph in @(@('inicio', 3), @('bucle', 6), @('fin', 3))) {
    $phase = $ph[0]; $cnt = $ph[1]; $lp = 'una vez'; if ($phase -eq 'bucle') { $lp = 'bucle' }
    New-Vfx "vfx_fp_relampago_pantalla_${sfx}_$phase" $SW $SH $cnt 20 $lp $Ox $Oy "Relampago $label en pantalla (480x270), fase $phase`: del baston a la mira, grueso cerca y fino lejos, con ramificaciones y destello en la mira" {
      param($f, $t)
      $seedBase = 1; if ($phase -eq 'bucle') { $seedBase = 50 }; if ($phase -eq 'fin') { $seedBase = 100 }
      $rng = New-Object System.Random($f * 17 + $seedBase)
      $pts = BoltPts $Ox $Oy $Gx $Gy 14 16 3 $rng
      $upto = 1.01; $style = 0
      if ($phase -eq 'inicio') { $upto = @(0.4, 0.75, 1.01)[$f] }
      if ($phase -eq 'fin') { $style = @(1, 2, 2)[$f] }
      $alive = -not ($phase -eq 'fin' -and $f -eq 2)
      if ($alive) { DrawBolt $pts 8 3 $ramp $upto $style }
      if ($phase -ne 'fin' -or $f -eq 0) {
        $base = [math]::Atan2($Gy - $Oy, $Gx - $Ox)
        for ($k = 0; $k -lt 4; $k++) {
          $idx = $rng.Next(2, 12); $u = $idx / 14.0; if ($u -ge $upto) { continue }
          $sgn = 1; if ($rng.NextDouble() -lt 0.5) { $sgn = -1 }
          DrawFork $pts[$idx][0] $pts[$idx][1] ($base + $sgn * (0.5 + $rng.NextDouble() * 0.7)) ((30 + $rng.NextDouble() * 25) * (1 - 0.5 * $u)) 4 $rng $ramp 2
        }
        for ($k = 0; $k -lt 5; $k++) {
          $idx = $rng.Next(1, 13); if (($idx / 14.0) -ge $upto) { continue }
          $ax2 = $pts[$idx][0]; $ay2 = $pts[$idx][1]; $aa = $rng.NextDouble() * 6.283
          $bx2 = $ax2 + [math]::Cos($aa) * (6 + $rng.Next(0, 6)); $by2 = $ay2 + [math]::Sin($aa) * (6 + $rng.Next(0, 6))
          $cx2 = $bx2 + [math]::Cos($aa + 1.2) * 5; $cy2 = $by2 + [math]::Sin($aa + 1.2) * 5
          ThickLine $ax2 $ay2 $bx2 $by2 1 $ramp[2]; ThickLine $bx2 $by2 $cx2 $cy2 1 $ramp[4]
        }
      }
      if (-not ($phase -eq 'fin' -and $f -ge 1)) {
        $rr = 7 + $rng.Next(0, 3)
        $g.EllD($Ox, $Oy, $rr + 5, $rr + 5, $ramp[0], 1); $g.Ell($Ox, $Oy, $rr, $rr, $ramp[1]); $g.Ell($Ox, $Oy, $rr * 0.65, $rr * 0.65, $ramp[2]); $g.Ell($Ox, $Oy, $rr * 0.3, $rr * 0.3, $ramp[4])
      }
      if ($upto -ge 1 -and $alive) {
        $rt = 5 + $rng.Next(0, 4); if ($phase -eq 'fin') { $rt = 4 }
        for ($k = 0; $k -lt 8; $k++) {
          $aa = $k * [math]::PI / 4 + $rng.NextDouble() * 0.4; $ll = $rt * (1.6 + $rng.NextDouble())
          ThickLine $Gx $Gy ($Gx + [math]::Cos($aa) * $ll) ($Gy + [math]::Sin($aa) * $ll) 1 $ramp[3]
        }
        $g.Ell($Gx, $Gy, $rt, $rt, $ramp[2]); $g.Ell($Gx, $Gy, $rt * 0.55, $rt * 0.55, $ramp[4])
      }
      for ($k = 0; $k -lt 12; $k++) {
        $u = $rng.NextDouble(); if ($u -ge $upto) { continue }
        Pt ($Ox + ($Gx - $Ox) * $u + $rng.Next(-16, 17)) ($Oy + ($Gy - $Oy) * $u + $rng.Next(-16, 17)) 1 $(if (($k % 2) -eq 0) { $ramp[2] } else { $ramp[4] })
      }
    }
  }

  # Carga en la punta del baston (64x64)
  New-Vfx "vfx_fp_relampago_carga_$sfx" 64 64 8 14 'bucle' 32 32 "Carga de relampago $label en la punta del baston: nucleo que pulsa y arcos que saltan" {
    param($f, $t)
    $rng = New-Object System.Random($f * 9 + 3); $rr = 5 + [math]::Sin(2 * [math]::PI * $t)
    $g.EllD(32, 32, $rr + 8, $rr + 8, $ramp[0], 1)
    for ($k = 0; $k -lt 6; $k++) {
      $aa = $rng.NextDouble() * 6.283; $ln = 14 + $rng.NextDouble() * 12
      DrawFork 32 32 $aa $ln 3 $rng $ramp 1
    }
    $g.Ell(32, 32, $rr, $rr, $ramp[1]); $g.Ell(32, 32, $rr * 0.65, $rr * 0.65, $ramp[2]); $g.Ell(32, 32, $rr * 0.3, $rr * 0.3, $ramp[4])
    for ($k = 0; $k -lt 4; $k++) { Pt (32 + $rng.Next(-26, 27)) (32 + $rng.Next(-26, 27)) 1 $ramp[3] }
  }

  # Impacto de frente (96x96)
  New-Vfx "vfx_fp_relampago_impacto_$sfx" 96 96 8 16 'una vez' 48 48 "Impacto de relampago $label visto de frente: destello, rayos dentados, anillo y chispas" {
    param($f, $t)
    $rng = New-Object System.Random(17)
    $Lf = @(8, 20, 32, 40, 42, 36, 26, 12)[$f]
    if ($f -ge 1 -and $f -le 5) { $rg = 8 + $f * 7; $g.Ring(48, 48, $rg, $rg, [math]::Max(1, 3 - [math]::Floor($f / 2)), $(if ($f -ge 4) { $ramp[1] } else { $ramp[2] })) }
    if ($f -ge 1 -and $f -le 5) { $g.EllD(48, 48, 8 + $f * 7 - 1, 8 + $f * 7 - 1, $ramp[0], 1) }
    for ($pass = 0; $pass -lt 2; $pass++) {
      $rng = New-Object System.Random(17)
      for ($k = 0; $k -lt 10; $k++) {
        $ang = $k * 2 * [math]::PI / 10 + $rng.NextDouble() * 0.3; $ln = $Lf * (0.75 + 0.25 * $rng.NextDouble()); $px = 48; $py = 48
        for ($s = 1; $s -le 4; $s++) {
          $ang += ($rng.NextDouble() - 0.5) * 0.5; $nr = 4 + ($ln - 4) * $s / 4.0
          $qx = 48 + [math]::Cos($ang) * $nr; $qy = 48 + [math]::Sin($ang) * $nr
          if ($pass -eq 0) { if ($f -le 5) { ThickLine $px $py $qx $qy 3 $ramp[1] } } else { ThickLine $px $py $qx $qy 1 $ramp[4] }
          $px = $qx; $py = $qy
        }
      }
    }
    if ($f -le 2) { $fr = 14 - $f * 2; $g.Ell(48, 48, $fr, $fr, $ramp[2]); $g.Ell(48, 48, $fr * 0.6, $fr * 0.6, $ramp[4]) }
    $r3 = New-Object System.Random($f * 5 + 1)
    for ($k = 0; $k -lt (12 - $f); $k++) { $aa = $r3.NextDouble() * 6.283; $dd = 6 + $r3.NextDouble() * 40; Pt (48 + $dd * [math]::Cos($aa)) (48 + $dd * [math]::Sin($aa)) 1 $(if (($k % 2) -eq 0) { $ramp[3] } else { $ramp[2] }) }
  }
}

