# ========== RELAMPAGO "MODERNO": haz estable con hebras trenzadas, nodos de energia y arcos cortos ==========
$dxA = $Gx - $Ox; $dyA = $Gy - $Oy; $lenA = [math]::Sqrt($dxA * $dxA + $dyA * $dyA)
$nxA = -$dyA / $lenA; $nyA = $dxA / $lenA

function AxisPt([double]$u) {
  $bend = 12 * [math]::Sin([math]::PI * $u)
  return , @(($Ox + $dxA * $u + $nxA * $bend), ($Oy + $dyA * $u + $nyA * $bend))
}

function ModernBeam($ramp, [int]$f, [int]$nf, [double]$upto, [int]$style, $rng) {
  $segs = 36; $PI2 = 2 * [math]::PI
  $axis = @()
  for ($i = 0; $i -le $segs; $i++) { $axis += AxisPt ($i / [double]$segs) }
  # nucleo y resplandor
  DrawBolt $axis 9 4 $ramp $upto $style
  # tres hebras trenzadas alrededor del eje
  if ($style -le 1) {
    for ($k = 0; $k -lt 3; $k++) {
      $prev = $null
      for ($i = 0; $i -le $segs; $i++) {
        $u = $i / [double]$segs; if ($u -gt $upto) { break }
        $amp = 11 * [math]::Pow([math]::Sin([math]::PI * $u), 0.6) * (1 - 0.4 * $u)
        $off = $amp * [math]::Sin($PI2 * 2.2 * $u + $k * 2.094 + $PI2 * $f / $nf) + ($rng.NextDouble() - 0.5) * 2.4 * [math]::Sin([math]::PI * $u)
        $cur = @(($axis[$i][0] + $nxA * $off), ($axis[$i][1] + $nyA * $off))
        if ($prev -ne $null) {
          if ($style -eq 0) { ThickLine ($prev[0]) ($prev[1]) ($cur[0]) ($cur[1]) 2 ($ramp[2]) }
          ThickLine ($prev[0]) ($prev[1]) ($cur[0]) ($cur[1]) 1 ($ramp[4])
        }
        $prev = $cur
      }
    }
  }
  if ($style -eq 0) {
    # nodos de energia que viajan por el haz
    for ($j = 0; $j -lt 3; $j++) {
      $u = (($f / [double]$nf) + $j / 3.0) % 1.0; if ($u -ge $upto) { continue }
      $p = AxisPt $u; $r = 5.5 * (1 - 0.45 * $u)
      $global:g.Ell($p[0], $p[1], $r + 1.5, $r + 1.5, $ramp[1]); $global:g.Ell($p[0], $p[1], $r, $r, $ramp[2]); $global:g.Ell($p[0], $p[1], $r * 0.55, $r * 0.55, $ramp[4])
    }
    # arcos cortos que saltan hacia afuera
    $na = [math]::Atan2($nyA, $nxA)
    for ($k = 0; $k -lt 7; $k++) {
      $idx = $rng.Next(3, 34); $u = $idx / [double]$segs; if ($u -ge $upto) { continue }
      $dirA = $na; if ($rng.NextDouble() -lt 0.5) { $dirA += [math]::PI }
      DrawFork ($axis[$idx][0]) ($axis[$idx][1]) ($dirA + ($rng.NextDouble() - 0.5) * 0.8) ((12 + $rng.NextDouble() * 12) * (1 - 0.4 * $u)) 3 $rng $ramp 1 0
    }
  }
  return , $axis
}

function LightningModern([string]$sfx, $ramp, [string]$label) {
  # Cinta repetible
  New-Vfx "vfx_fp_relampago_moderno_haz_$sfx" 256 48 8 14 'bucle' 0 24 "Relampago moderno $label como cinta repetible (256x48): nucleo estable, tres hebras trenzadas y arcos cortos" {
    param($f, $t)
    $rng = New-Object System.Random($f * 11 + 5); $PI2 = 2 * [math]::PI
    $axis = @(); for ($i = 0; $i -le 32; $i++) { $axis += , @(($i * 8.0), 24.0) }
    DrawBolt $axis 8 8 $ramp 1.01 0
    for ($k = 0; $k -lt 3; $k++) {
      $prev = $null
      for ($i = 0; $i -le 64; $i++) {
        $u = $i / 64.0; $x = 256 * $u
        $off = 9 * [math]::Sin($PI2 * 3 * $u + $k * 2.094 + $PI2 * $f / 8.0) + ($rng.NextDouble() - 0.5) * 2 * [math]::Sin([math]::PI * $u)
        $cur = @($x, (24 + $off))
        if ($prev -ne $null) { ThickLine ($prev[0]) ($prev[1]) ($cur[0]) ($cur[1]) 2 ($ramp[2]); ThickLine ($prev[0]) ($prev[1]) ($cur[0]) ($cur[1]) 1 ($ramp[4]) }
        $prev = $cur
      }
    }
    for ($k = 0; $k -lt 4; $k++) {
      $sx = 20 + $rng.NextDouble() * 216; $dirA = -[math]::PI / 2; if ($rng.NextDouble() -lt 0.5) { $dirA = [math]::PI / 2 }
      DrawFork $sx 24 ($dirA + ($rng.NextDouble() - 0.5) * 0.8) (10 + $rng.NextDouble() * 10) 3 $rng $ramp 1 0
    }
    for ($k = 0; $k -lt 10; $k++) { Pt ($rng.Next(0, 256)) (24 + $rng.Next(-17, 18)) 1 $(if (($k % 2) -eq 0) { $ramp[2] } else { $ramp[4] }) }
  }

  foreach ($ph in @(@('inicio', 3), @('bucle', 6), @('fin', 3))) {
    $phase = $ph[0]; $cnt = $ph[1]; $lp = 'una vez'; if ($phase -eq 'bucle') { $lp = 'bucle' }
    New-Vfx "vfx_fp_relampago_moderno_pantalla_${sfx}_$phase" $SW $SH $cnt 20 $lp $Ox $Oy "Relampago moderno $label en pantalla (480x270), fase $phase`: haz estable ligeramente curvo del baston a la mira con hebras trenzadas, nodos de energia y arcos" {
      param($f, $t)
      $seedBase = 3; if ($phase -eq 'bucle') { $seedBase = 60 }; if ($phase -eq 'fin') { $seedBase = 120 }
      $rng = New-Object System.Random($f * 19 + $seedBase)
      $upto = 1.01; $style = 0
      if ($phase -eq 'inicio') { $upto = @(0.4, 0.75, 1.01)[$f] }
      if ($phase -eq 'fin') { $style = @(1, 2, 2)[$f] }
      $nf = $cnt; if ($phase -ne 'bucle') { $nf = 6 }
      $ff = $f; if ($phase -eq 'inicio') { $ff = $f * 2 }; if ($phase -eq 'fin') { $ff = $f * 2 + 1 }
      $alive = -not ($phase -eq 'fin' -and $f -eq 2)
      if ($alive) { [void](ModernBeam $ramp $ff $nf $upto $style $rng) }
      # orbe del baston con rayos
      if (-not ($phase -eq 'fin' -and $f -ge 1)) {
        $rr = 8 + $rng.Next(0, 3)
        $g.EllD($Ox, $Oy, $rr + 6, $rr + 6, $ramp[0], 1); $g.Ell($Ox, $Oy, $rr, $rr, $ramp[1]); $g.Ell($Ox, $Oy, $rr * 0.7, $rr * 0.7, $ramp[2]); $g.Ell($Ox, $Oy, $rr * 0.35, $rr * 0.35, $ramp[4])
        for ($k = 0; $k -lt 8; $k++) { $aa = $k * [math]::PI / 4 + $rng.NextDouble() * 0.3; ThickLine ($Ox + [math]::Cos($aa) * ($rr + 2)) ($Oy + [math]::Sin($aa) * ($rr + 2)) ($Ox + [math]::Cos($aa) * ($rr + 7 + $rng.Next(0, 5))) ($Oy + [math]::Sin($aa) * ($rr + 7 + $rng.Next(0, 5))) 1 ($ramp[3]) }
      }
      # destello y anillo en la mira
      if ($upto -ge 1 -and $alive) {
        $rt = 7 + $rng.Next(0, 3); if ($phase -eq 'fin') { $rt = 5 }
        $g.EllD($Gx, $Gy, $rt + 7, $rt + 7, $ramp[0], 1)
        $g.Ring($Gx, $Gy, $rt + 4, $rt + 4, 1, $ramp[2])
        for ($k = 0; $k -lt 8; $k++) { $aa = $k * [math]::PI / 4 + $rng.NextDouble() * 0.4; ThickLine $Gx $Gy ($Gx + [math]::Cos($aa) * $rt * 2.2) ($Gy + [math]::Sin($aa) * $rt * 2.2) 1 ($ramp[3]) }
        $g.Ell($Gx, $Gy, $rt, $rt, $ramp[2]); $g.Ell($Gx, $Gy, $rt * 0.55, $rt * 0.55, $ramp[4])
      }
      for ($k = 0; $k -lt 14; $k++) {
        $u = $rng.NextDouble(); if ($u -ge $upto) { continue }
        $p = AxisPt $u
        Pt ($p[0] + $rng.Next(-14, 15)) ($p[1] + $rng.Next(-14, 15)) 1 $(if (($k % 2) -eq 0) { $ramp[2] } else { $ramp[4] })
      }
    }
  }
}

